var t=`0675-alloco`;var i=`world-0675`;var o=`CI`;var a=`western-africa`;var s=4;var r=44;var l={en:`Alloco`,ua:`Алоко`};var d={en:`Alloco is a Côte d'Ivoire classic prepared with plantain, yellow onion, tomato, scotch bonnet pepper. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Алоко, страва кухні країни Кот-д'Івуар зі складниками: плантан, жовта цибуля, помідор, перець скотч-боннет. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var p=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:9,i:[[`plantain`,750,`g`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 19 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 19 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:19,i:[[`sunflower-oil`,650,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,180,`g`],[`tomato`,260,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`red-palm-oil`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`parsley`,15,`g`]]}];var c={slug:t,id:i,country:`CI`,region:a,servings:4,minutes:44,title:l,text:d,steps:p};export{o as country,c as default,i as id,r as minutes,a as region,s as servings,t as slug,p as steps,d as text,l as title};